def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast feature extraction
    my_last = 'C'
    opp_last = 'C'
    cc = cd = dc = dd = 0
    my_d = opp_d = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            my_d += 1
            if b == 'C':
                dc += 1
            else:
                dd += 1
        if b == 'D':
            opp_d += 1
    my_last, opp_last = history[-1]

    # Early-game: cooperate, but tolerate an early defection by one round only.
    if n <= 3:
        if opp_last == 'D' and n >= 2 and history[-2][1] == 'D':
            return 'D'
        return 'C'

    # Tail analysis of recent opponent behavior
    recent = history[-8:] if n >= 8 else history
    recent_opp_d = sum(1 for a, b in recent if b == 'D')
    recent_my_d = sum(1 for a, b in recent if a == 'D')
    recent_len = len(recent)

    opp_rate = opp_d / n
    remaining = 100 - n

    # Endgame: exploit hard, except against near-perfect cooperators where cooperating is safer.
    if remaining <= 5:
        if opp_d == 0:
            return 'D'
        return 'D'

    # Against a near-always-cooperator, exploit but sprinkle cooperation so a
    # forgiving/punishing partner doesn't lock into DD near the end.
    if opp_rate <= 0.08 and n >= 12:
        if remaining <= 20:
            return 'D'
        if rng.random() < 0.82:
            return 'D'
        return 'C'

    # Against near-always-defector, defect mostly; rare probes.
    if opp_rate >= 0.85 and n >= 8:
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # Detect sustained opponent defection and respond firmly.
    # Longest current run of opponent D's:
    run_o = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_o += 1
        else:
            break
    # Longest current run of our D's:
    run_m = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            run_m += 1
        else:
            break

    # If opponent has just defected:
    if opp_last == 'D':
        # Forgive a single isolated defection when overall cooperation is high.
        if opp_rate < 0.22 and run_o == 1 and my_last == 'C':
            # Forgive once; if it happens again soon, punish.
            if n >= 3 and history[-2][1] == 'D':
                return 'D'
            return 'C'
        # Long opponent D-run: keep defecting, but occasionally test C to
        # break DD lock-in with reciprocal opponents.
        if run_o >= 4:
            if run_m >= 4 and rng.random() < 0.35:
                return 'C'
            return 'D'
        if run_o >= 2:
            return 'D'
        # Single defection and opp_rate moderate: retaliate.
        return 'D'

    # Opponent just cooperated.
    # If we're stuck in our own long D-run, return to C to re-establish CC.
    if my_last == 'D':
        if run_m >= 3:
            return 'C'
        # If opponent cooperates after we defected, and they usually cooperate,
        # cooperate too (TFT-like) unless we're in exploit mode near end.
        if opp_rate < 0.35:
            return 'C'
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    # Both cooperated last round.
    # Prefer CC. Against moderately defective opponents, punish recent patterns.
    if recent_opp_d * 2 >= recent_len:
        # Opponent has been defecting often recently: retaliate/preempt.
        return 'D' if rng.random() < 0.8 else 'C'

    # Against very cooperative opponents, occasional safe exploitation.
    if opp_rate <= 0.18 and remaining > 25:
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    # Against moderately cooperative opponents, mostly C with occasional D.
    if rng.random() < max(0.0, (opp_rate - 0.1) * 0.6):
        return 'D'
    return 'C'
